// Handoff: the end-of-session note, written from what the session did.
//
// While you work, the host keeps a record of the files Claude changed and the
// checks it ran. `/handoff` writes HANDOFF.md from that record and from git,
// then adds Claude's own account under a separate heading. The next session in
// the project is handed the file with its first message.

import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import {
  EMPTY,
  FILE,
  isCheck,
  oneLine,
  pickup,
  QUESTION,
  recordCheck,
  recordFile,
  relative,
  render,
  writtenAt,
} from './handoff'
import type { HandoffInput } from './handoff'

const ledger = atom({ plugin: 'session-handoff', key: 'ledger' } as const, EMPTY)

let root = ''

/** One git command's output lines, or null when git refused or is not there. */
async function git($: EngineInterface, ...argv: string[]): Promise<string[] | null> {
  try {
    const ran = await $.process.run(['git', ...argv], { cwd: root, timeoutMs: 10_000 })

    if (ran.exitCode !== 0) return null

    return ran.stdout
      .split('\n')
      .map(line => line.trimEnd())
      .filter(line => line !== '')
  } catch {
    return null
  }
}

/** Marks where the session starts: the time, and the commit that was checked out. */
async function begin($: EngineInterface): Promise<void> {
  root = await $.session.root()

  if ((await read($, ledger)).startedAt > 0) return

  const startedAt = await $.clock.now()
  const head = await git($, 'rev-parse', 'HEAD')

  await update($, ledger, was =>
    was.startedAt > 0 ? was : { ...was, startedAt, startSha: head?.[0] ?? null },
  )
}

/** Asks the model for its own account of the session, over the session's transcript. */
async function summarize($: EngineInterface): Promise<{ summary: string | null; note: string }> {
  try {
    const reply = await $.model.fork({ prompt: QUESTION })

    if (reply.isAnswered) return { summary: reply.text, note: '' }

    switch (reply.reason) {
      case 'nothing-to-fork':
        return { summary: null, note: 'the session has no conversation to summarize yet.' }
      case 'api-error':
        return { summary: null, note: `the model call failed (${reply.error}).` }
      case 'aborted':
        return { summary: null, note: 'the model call was interrupted.' }
      default:
        return { summary: null, note: 'the model returned no text.' }
    }
  } catch {
    return { summary: null, note: 'the model could not be asked.' }
  }
}

async function write($: EngineInterface, isQuick: boolean): Promise<string> {
  root = await $.session.root()

  const path = `${root}/${FILE}`

  if (await $.fs.exists(path)) {
    let existing = ''

    try {
      existing = await $.fs.read(path)
    } catch {
      existing = ''
    }

    // A HANDOFF.md someone else wrote is theirs: it is never overwritten.
    if (writtenAt(existing) === null) {
      return `${FILE} exists and was not written by Handoff. Move or rename it, then run /handoff again.`
    }
  }

  const now = await read($, ledger)
  const branch = await git($, 'rev-parse', '--abbrev-ref', 'HEAD')
  const commits =
    now.startSha === null
      ? null
      : await git($, 'log', '--oneline', '--no-decorate', '-n', '50', `${now.startSha}..HEAD`)
  const status = await git($, 'status', '--short')
  const asked = isQuick
    ? { summary: null, note: 'none was asked for (/handoff quick).' }
    : await summarize($)

  const input: HandoffInput = {
    now: await $.clock.now(),
    ledger: now,
    branch: branch?.[0] ?? null,
    commits: commits ?? [],
    uncommitted: (status ?? []).filter(line => !line.endsWith(` ${FILE}`)),
    summary: asked.summary,
    summaryNote: asked.note,
  }

  await $.fs.write(path, render(input))

  return oneLine(input)
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'handoff',
      description: 'Write HANDOFF.md: what this session did, for the next one to pick up',
      argumentHint: '[quick]',
    })
    await begin($)

    return next(e)
  })

  // /clear, /resume and /branch reset the session's state and raise no session.start.
  on('classic.SessionStart', { source: ['clear', 'resume', 'fork'] }, async ($, e, next) => {
    await begin($)

    return next(e)
  })

  on('command.run', { command: 'handoff' }, async ($, e) => {
    const args = e.args.trim()

    if (args !== '' && args !== 'quick') {
      return { text: 'Usage: /handoff writes the note with a model summary; /handoff quick leaves the summary out.' }
    }

    return { text: await write($, args === 'quick') }
  })

  // ------------------------------------------------------------- watching

  on('tool.call', { tool: ['Edit', 'Write', 'NotebookEdit'] }, async ($, e, next) => {
    const ran = await next(e)

    if (ran.deny !== undefined || ran.isError === true) return ran

    const path = relative(root, 'file_path' in e ? e.file_path : e.notebook_path)

    await update($, ledger, was => recordFile(was, path))

    return ran
  })

  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    const ran = await next(e)

    if (ran.deny !== undefined) return ran

    const record = ran.isError === true ? undefined : ran.result

    if (isCheck(e.command) && record?.backgroundTaskId === undefined) {
      const ok = ran.isError !== true && record?.interrupted !== true

      await update($, ledger, was => recordCheck(was, e.command, ok))
    }

    // Files a shell command changed count as changed, as an edit's do.
    const changed = (record?.bashEditDiff?.files ?? []).map(file => relative(root, file.filePath))

    if (changed.length > 0) {
      await update($, ledger, was => changed.slice(0, 50).reduce(recordFile, was))
    }

    return ran
  })

  // ------------------------------------------------------------ picking up

  // A conversation's first message carries the last handoff, when there is a fresh one.
  on('prompt.context', async ($, e, next) => {
    const below = await next(e)

    root = await $.session.root()

    const path = `${root}/${FILE}`

    if (!(await $.fs.exists(path))) return below

    let text = ''

    try {
      text = await $.fs.read(path)
    } catch {
      return below
    }

    const found = pickup(text, await $.clock.now())

    if ('skip' in found) {
      if (found.skip !== '') $.ui.toast(found.skip)

      return below
    }

    $.ui.toast(
      `Loaded ${FILE} from ${found.days === 0 ? 'today' : found.days === 1 ? 'yesterday' : `${found.days} days ago`}.`,
    )

    return {
      ...below,
      blocks: [...below.blocks.filter(block => block.name !== 'handoff'), { name: 'handoff', text: found.text }],
    }
  })
}

